import React from 'react';
import { projects } from '../data/projects';

const featured = projects.find(p => p.featured);
const others = projects.filter(p => !p.featured);

export default function Projects() {
  return (
    <section id="projects">
      <div className="section-inner">
        <div className="section-label">// 03 — projects</div>
        <h2 className="section-title">Featured <span>Work</span></h2>

        {/* FEATURED PROJECT */}
        {featured && (
          <div style={{
            background: 'linear-gradient(135deg, #111111, #181818)',
            border: '1px solid rgba(255,107,26,0.2)',
            borderRadius: 12, overflow: 'hidden', marginBottom: '2rem',
            display: 'grid', gridTemplateColumns: '1fr 1fr',
            transition: 'all 0.3s'
          }}>
            {/* Preview pane */}
            <div style={{
              background: 'linear-gradient(135deg, #0d0d0d, #1a1a1a)',
              padding: '2rem', display: 'flex', alignItems: 'center',
              justifyContent: 'center', minHeight: 240, position: 'relative', overflow: 'hidden'
            }}>
              <div style={{
                position: 'absolute', inset: 0,
                background: 'radial-gradient(circle at 30% 50%, rgba(255,107,26,0.12), transparent 60%)'
              }} />
              <div style={{
                width: '100%', maxWidth: 280,
                background: 'rgba(255,255,255,0.04)',
                border: '1px solid rgba(255,107,26,0.2)',
                borderRadius: 8, padding: '1rem',
                fontFamily: 'Space Mono, monospace', fontSize: '0.65rem', position: 'relative'
              }}>
                <div style={{ color: 'var(--orange)', marginBottom: 8, letterSpacing: '0.1em' }}>ETHIO REFERRAL DASHBOARD</div>
                {[100, 75, 55].map((w, i) => (
                  <div key={i} style={{
                    height: 6, borderRadius: 3, marginBottom: 6,
                    background: `rgba(255,107,26,${0.4 - i * 0.12})`,
                    width: `${w}%`
                  }} />
                ))}
                <div style={{ display: 'flex', gap: 6, marginTop: 10 }}>
                  {[['127', 'Referrals'], ['43', 'Hospitals'], ['98%', 'Uptime']].map(([val, label]) => (
                    <div key={label} style={{
                      flex: 1, background: 'rgba(255,255,255,0.04)',
                      border: '1px solid rgba(255,107,26,0.15)',
                      borderRadius: 4, padding: 6, textAlign: 'center'
                    }}>
                      <div style={{ color: 'var(--orange)', fontSize: '0.65rem', fontWeight: 700 }}>{val}</div>
                      <div style={{ color: 'var(--muted)', fontSize: '0.5rem', marginTop: 2 }}>{label}</div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Info pane */}
            <div style={{ padding: '2rem' }}>
              {featured.status && (
                <div style={{
                  display: 'inline-flex', alignItems: 'center', gap: 6,
                  background: 'rgba(255,107,26,0.12)', border: '1px solid rgba(255,107,26,0.3)',
                  color: 'var(--orange)', fontSize: '0.65rem', letterSpacing: '0.12em',
                  textTransform: 'uppercase', padding: '4px 12px', borderRadius: 20, marginBottom: '1rem'
                }}>
                  <span style={{ width: 5, height: 5, borderRadius: '50%', background: 'var(--orange)', display: 'inline-block', animation: 'pulse 1.5s infinite' }} />
                  {featured.status}
                </div>
              )}
              <h3 style={{ fontSize: '1.4rem', fontWeight: 800, letterSpacing: '-0.02em', marginBottom: '0.75rem' }}>
                {featured.title}
              </h3>
              <p style={{ color: 'var(--muted)', fontSize: '0.85rem', lineHeight: 1.8, marginBottom: '1.5rem' }}>
                {featured.description}
              </p>
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginBottom: '1.5rem' }}>
                {featured.tags.map(t => <span key={t} className="tag">{t}</span>)}
              </div>
              <div style={{ display: 'flex', gap: '1rem' }}>
                <a href={featured.github} target="_blank" rel="noopener noreferrer"
                  style={{ color: 'var(--orange)', textDecoration: 'none', fontSize: '0.75rem', letterSpacing: '0.1em', textTransform: 'uppercase', fontWeight: 700 }}>
                  → GitHub
                </a>
              </div>
            </div>
          </div>
        )}

        {/* OTHER PROJECTS GRID */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '1.5rem' }}>
          {others.map(p => (
            <div key={p.id} style={{
              background: 'var(--surface)', border: '1px solid var(--border)',
              borderRadius: 10, padding: '1.5rem', transition: 'all 0.25s',
              cursor: 'default'
            }}
            onMouseEnter={e => { e.currentTarget.style.borderColor = 'rgba(255,107,26,0.4)'; e.currentTarget.style.transform = 'translateY(-3px)'; }}
            onMouseLeave={e => { e.currentTarget.style.borderColor = 'var(--border)'; e.currentTarget.style.transform = 'none'; }}>
              <div style={{ fontSize: '1.5rem', marginBottom: '1rem' }}>{p.icon}</div>
              <h3 style={{ fontSize: '0.95rem', fontWeight: 700, marginBottom: '0.5rem' }}>{p.title}</h3>
              <p style={{ color: 'var(--muted)', fontSize: '0.78rem', lineHeight: 1.7, marginBottom: '1rem' }}>{p.description}</p>
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: 4, marginBottom: '1rem' }}>
                {p.tags.map(t => <span key={t} className="tag">{t}</span>)}
              </div>
              <a href={p.github} target="_blank" rel="noopener noreferrer"
                style={{ color: 'var(--orange)', fontSize: '0.75rem', textDecoration: 'none', fontWeight: 700 }}>
                → View on GitHub
              </a>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}
